#!/usr/bin/env python3
"""FEATURE INVENTORY: Park Commander + Trip Planners (Nov 8 2026; Brandon: 'keep all features', the last polish lost many).
Reads the page and script files below and lists every DOM id, JS function, URL parameter, localStorage key, data-action, button,
form field, aria-label/title, keyboard shortcut and internal link. Writes
  FEATURES-commander-tripplanner.md          (people read this)
  tests/features-commander-tripplanner.json  (tests/test_feature_inventory_nov8.py checks every item is still there)
  python3 .github/scripts/kpc_feature_inventory.py           write both (only ADD items: an item that vanished stays listed and fails the test)
  python3 .github/scripts/kpc_feature_inventory.py --check   exit 1 if any listed item is gone
  python3 .github/scripts/kpc_feature_inventory.py --selftest"""
import json, pathlib, re, sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
PAGES = {'Park Commander': ['finder.html', 'finder.js', 'finder.css'],
         'Kentucky Trip Planner': ['kpc-planner.html', 'kpc-planner.js'],
         'US Trip Planner': ['kpc-planner-us.html', 'kpc-us-planner.js'],
         'Shared map parts': ['kpc-map-extras.js', 'kpc-trails-layer.js', 'kpc-padus-layer.js', 'kpc-tools.css', 'gis-overlays.js', 'kpc-bounds.js',
                             'kpc-getting-in.js', 'kpc-gps.js', 'kpc-gps-wire.js']}
BASE = ROOT / 'tests/features-commander-tripplanner.json'
MD = ROOT / 'FEATURES-commander-tripplanner.md'
KINDS = {'id': 'DOM ids (controls, panels, layers, legend)', 'fn': 'JS functions', 'param': 'URL parameters', 'ls': 'localStorage keys',
         'data': 'data-* actions (buttons/toggles in cards and lists)', 'btn': 'Button labels', 'input': 'Form fields (name=)',
         'aria': 'aria-labels', 'title': 'Tooltips (title=)', 'key': 'Keyboard shortcuts', 'link': 'Internal page links',
         'export': 'Export / print / share'}


def items(src):
    s = set()
    add = lambda k, v: s.add(f'{k}:{v.strip()}') if v and v.strip() else None
    for m in re.findall(r'\bid=["\']([A-Za-z][\w-]*)["\']', src): add('id', m)
    for m in re.findall(r'getElementById\(["\']([\w-]+)["\']\)', src): add('id', m)
    for m in re.findall(r'\$\(["\']([A-Za-z][\w-]*)["\']\)', src): add('id', m)
    for m in re.findall(r'\bfunction\s+([A-Za-z_$][\w$]*)\s*\(', src): add('fn', m)
    for m in re.findall(r'\.(?:get|has)\(["\']([a-z][\w-]{0,24})["\']\)', src):
        if re.search(r'(searchParams|URLSearchParams|location\.(search|hash))', src): add('param', m)
    for m in re.findall(r'[?&]([a-z][\w-]{1,20})=(?:0|1|on|off)\b', src): add('param', m)
    for m in re.findall(r'\[\?&\]([a-z][\w-]{1,20})=', src): add('param', m)
    for m in re.findall(r'localStorage\.(?:getItem|setItem|removeItem)\(["\']([^"\']+)["\']', src): add('ls', m)
    for m in re.findall(r'\bdata-([a-z][\w-]*)=["\']([\w-]+)["\']', src):
        if m[0] in ('act', 'action', 'layer', 'tab', 'tool', 'rv', 'go', 'more', 'drop', 'kx', 'town'): add('data', f'{m[0]}={m[1]}')
    for m in re.findall(r'<button[^>]*>([^<]{2,60})</button>', src): add('btn', m)
    for m in re.findall(r'<(?:input|select|textarea)[^>]*\bname=["\']([\w-]+)', src): add('input', m)
    for m in re.findall(r'aria-label=["\']([^"\'$]{2,60})["\']', src): add('aria', m)
    for m in re.findall(r'\btitle=["\']([^"\'$<]{2,60})["\']', src): add('title', m)
    for m in re.findall(r'e\.key\s*===?\s*["\']([^"\']{1,12})["\']', src): add('key', m)
    for m in re.findall(r'href=["\']((?:\.\/)?[\w-]+\.html)(?:[#?][^"\']*)?["\']', src): add('link', m)
    for m in re.findall(r'\b(window\.print|navigator\.share|navigator\.clipboard|download=|\.csv|\.gpx|\.kml)\b', src): add('export', m)
    return s


def current():
    out = {}
    for page, files in PAGES.items():
        for f in files:
            p = ROOT / f
            if p.is_file(): out[f] = sorted(items(p.read_text(encoding='utf-8', errors='replace')))
    return out


def missing(base, now):
    return {f: sorted(set(v) - set(now.get(f, []))) for f, v in base.items() if set(v) - set(now.get(f, []))}


def write(base):
    with open(BASE, 'w', newline='', encoding='utf-8') as fh: json.dump(base, fh, indent=0, sort_keys=True); fh.write('\n')
    L = ['# Feature inventory: Park Commander and Trip Planners', '',
         "Brandon (Nov 8 2026): keep every feature. Generated by `.github/scripts/kpc_feature_inventory.py` from the page and script",
         'files; `tests/test_feature_inventory_nov8.py` fails if any item below disappears. Re-run the script after ADDING features',
         '(it never drops an item: removing a feature on purpose means deleting its line from the JSON in the same commit, with the reason).', '']
    total = sum(len(v) for v in base.values())
    L.append(f'**{total} items** in {len(base)} files.'); L.append('')
    for page, files in PAGES.items():
        L.append(f'## {page}'); L.append('')
        for f in files:
            if f not in base: continue
            L.append(f'### `{f}` ({len(base[f])} items)'); L.append('')
            for k, label in KINDS.items():
                v = [x.split(':', 1)[1] for x in base[f] if x.startswith(k + ':')]
                if v: L.append(f'- **{label}** ({len(v)}): ' + ', '.join(f'`{x}`' for x in v))
            L.append('')
    with open(MD, 'w', newline='', encoding='utf-8') as fh: fh.write('\n'.join(L) + '\n')
    return total


def main():
    now = current()
    if '--selftest' in sys.argv:
        s = items('<button id="go" aria-label="Go now">Go</button><script>function zap(){};new URLSearchParams(location.search).get("candidates");localStorage.getItem("kpc.trip")</script>')
        want = {'id:go', 'fn:zap', 'param:candidates', 'ls:kpc.trip', 'btn:Go', 'aria:Go now'}
        ok = want <= s and missing({'a': ['id:x']}, {'a': []}) == {'a': ['id:x']}
        print('SELFTEST PASS' if ok else f'SELFTEST FAIL {sorted(want - s)}'); return 0 if ok else 1
    base = json.loads(BASE.read_text()) if BASE.is_file() else {}
    gone = missing(base, now)
    if '--check' in sys.argv:
        for f, v in gone.items(): print(f'GONE {f}: {v}')
        print('all inventory items present' if not gone else f'{sum(map(len, gone.values()))} items gone'); return 1 if gone else 0
    merged = {f: sorted(set(base.get(f, [])) | set(now.get(f, []))) for f in set(base) | set(now)}
    print(write(merged), 'items written', '' if not gone else f'(WARNING {sum(map(len, gone.values()))} listed items are gone)')
    return 0


if __name__ == '__main__':
    sys.exit(main())
